import{_ as o,o as t,c as a,a2 as i}from"./chunks/framework.7nMnW4XS.js";const p=JSON.parse('{"title":"ADR-061 — Surface hotspots are regions, not points (axis-aligned region_bounds on SurfaceSite)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/ADR-061.md","filePath":"adr/ADR-061.md"}'),s={name:"adr/ADR-061.md"};function n(r,e,c,d,l,u){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-061-—-surface-hotspots-are-regions-not-points-axis-aligned-region-bounds-on-surfacesite" tabindex="-1">ADR-061 — Surface hotspots are regions, not points (axis-aligned <code>region_bounds</code> on <code>SurfaceSite</code>) <a class="header-anchor" href="#adr-061-—-surface-hotspots-are-regions-not-points-axis-aligned-region-bounds-on-surfacesite" aria-label="Permalink to &quot;ADR-061 — Surface hotspots are regions, not points (axis-aligned `region_bounds` on `SurfaceSite`)&quot;">​</a></h1><blockquote><p>Status · Accepted Date · 2026-05-30 Closes into · <code>static/data/schemas/surface-site.schema.json</code> (schema additions) + <code>src/types/surface-site.ts</code> (TS type additions) Related · RFC-017 (Surface Hotspots, v0.7 — this ADR supersedes the disc/point geometry choice made there), Issue <a href="https://github.com/chipi/orrery/issues/283" target="_blank" rel="noreferrer">#283</a> (Surface hotspots v2 epic), Issue <a href="https://github.com/chipi/orrery/issues/284" target="_blank" rel="noreferrer">#284</a> (follow-on base sphere texture LOD) Triggered by · Visual review of v0.7 surface hotspots (2026-05-30): the current disc primitive is dishonest about both image footprint and semantic extent; selection halos decouple from content; layer transitions read as stickers, not terrain</p></blockquote><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The original surface-hotspots design (PRD-014 / RFC-017) modelled each site as a <strong>point</strong> — <code>(lat, lon)</code> plus an optional <code>location_uncertainty_m</code> radius. The Tier-2 patches (<code>hotspot-surface-patch.ts</code>) render this point as a circular <code>CircleGeometry</code> disc on the sphere, with a larger regional ring beneath. The disc diameter is fixed (1 km detail, 3 km regional context) and explicitly stylized — the source modal admits <em>&quot;3:1 ratio is a stylized &#39;you are HERE&#39; callout — at true scale HiRISE would be a sub-pixel speck inside the CTX disc.&quot;</em></p><p>Reviewing the actual experience in May 2026 surfaced four failures (full analysis in #283):</p><ol><li>The disc shape encodes nothing about the data — it is neither true footprint nor named region.</li><li>At mid-zoom, the hard-edged circle reads as a sticker pasted on the sphere, not as terrain data.</li><li>On the moon, the selection halo decouples from the disc into a giant blue ring floating in empty space around the much smaller dark disc.</li><li>At deepest zoom, nothing communicates that the user has crossed the imagery&#39;s resolving power — they read &quot;Mars is blurry&quot; instead of &quot;I&#39;m zooming past pixels.&quot;</li></ol><p>NASA&#39;s two reference families solve these honestly by encoding shape:</p><ul><li><strong>Image-extent rectangles</strong> (Perseverance location map): each HiRISE swath is drawn at its actual rectangular ground footprint.</li><li><strong>Region-of-interest rectangles</strong> (Lunar South Pole moonbase plan): named areas — &quot;Connecting Ridge&quot;, &quot;Haworth&quot;, &quot;Malapert Massif&quot; — are translucent quads bounded by the semantic region.</li></ul><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><strong>Each surface site gains an optional <code>region_bounds</code></strong> — an axis-aligned <code>{ lat_min, lat_max, lon_min, lon_max }</code> quad — plus <code>region_kind</code> (enum: <code>landing_ellipse | traverse_bbox | roi_quad | image_swath</code>) and <code>region_bearing_deg</code> (for rotated ellipses).</p><ul><li><strong>Schema (<code>surface-site.schema.json</code>):</strong> all three fields added as optional. An <code>if/then</code> rule enforces <code>region_bounds</code> requires <code>kind: &#39;surface&#39;</code>. Antimeridian-crossing regions are split into two entries in v1 (lat_min ≤ lat_max and lon_min ≤ lon_max enforced).</li><li><strong>TypeScript (<code>src/types/surface-site.ts</code>):</strong> mirrored as <code>RegionBounds</code> + <code>RegionKind</code> types + three optional fields on <code>SurfaceSite</code>.</li><li><strong>Field ordering:</strong> <code>region_bounds</code> + <code>region_kind</code> sit immediately after <code>lat</code> / <code>lon</code> in both schema and serialized JSON to keep geometry grouped (enforced by the Slice 1 backfill script&#39;s <code>reorder()</code>).</li><li><strong>Backward compat:</strong> all three fields are optional. Sites without <code>region_bounds</code> continue to render via the legacy disc primitive until Slice 3 of #283 replaces it. The backfill script (<code>scripts/mockups/backfill-region-bounds.mjs</code>) populates 19 moon and 16 mars surface sites with documented landing ellipses and rover traverse bboxes — sources cited inline in the script.</li></ul><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to &quot;Alternatives considered&quot;">​</a></h2><ul><li><strong>Polygon vertices (<code>Array&lt;{lat, lon}&gt;</code>)</strong> — strictly more expressive (arbitrary shape), but 95% of sites are landing ellipses or rover wander envelopes that an AABB captures adequately. Polygons add complexity (winding order, self-intersection checks) without payoff for v1. Can be added later (<code>region_polygon</code> alongside <code>region_bounds</code>) if a real need surfaces.</li><li><strong>Rotated ellipse (<code>{cx, cy, a, b, bearing}</code>)</strong> — closer to the actual physical shape of a Mars descent ellipse, but harder to backfill (no public source publishes ellipses in this canonical form) and harder to render as a click target on a curved sphere. Decided to store the AABB and add an optional <code>region_bearing_deg</code> for rendering hint — the actual ellipse can be drawn inside the box when bearing is set.</li><li><strong>Reuse <code>location_uncertainty_m</code></strong> — would have meant keeping the circle and just changing visual treatment. Rejected because the <em>shape</em> is the dishonesty; keeping a circle means accepting it.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Slices 2–6 of #283 can now consume the new schema without further data changes.</li><li>TA.md ADR table needs updating to mark ADR-059, ADR-060, ADR-062 still reserved (this ADR claims ADR-061 from the v0.7 RFC-017 reservation pool).</li><li>One inaccurate forward-reference in <code>src/types/surface-site.ts</code> (a comment that misattributed ADR-061 to the Tier 3 panorama field) is fixed in this same change.</li><li>The legacy disc primitive in <code>hotspot-surface-patch.ts</code> stays for now — Slice 3 of #283 replaces it. During the transition, both rendering paths exist; the dispatcher picks based on <code>region_bounds</code> presence.</li></ul>',15)])])}const g=o(s,[["render",n]]);export{p as __pageData,g as default};
